package br.com.itbn.sisdent.controller;
import br.com.itbn.sisdent.dto.*; import br.com.itbn.sisdent.service.*; import jakarta.validation.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/organizations/{organizationId}/clinical") public class ClinicalRecordController {private final ClinicalRecordService encounters; private final OdontogramService odontogram; public ClinicalRecordController(ClinicalRecordService e,OdontogramService o){encounters=e;odontogram=o;}
 @GetMapping("/encounters") public PageResponse<ClinicalEncounterResponse> list(@PathVariable UUID organizationId,@RequestParam UUID clinicUnitId,@RequestParam UUID patientId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return encounters.list(organizationId,clinicUnitId,patientId,page,size);}@PostMapping("/encounters") public ResponseEntity<ClinicalEncounterResponse> create(@PathVariable UUID organizationId,@Valid @RequestBody ClinicalEncounterCreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(encounters.create(organizationId,r));}@GetMapping("/encounters/{id}") public ClinicalEncounterResponse get(@PathVariable UUID organizationId,@PathVariable UUID id,@RequestParam UUID clinicUnitId){return encounters.get(organizationId,clinicUnitId,id);}@PutMapping("/encounters/{id}") public ClinicalEncounterResponse update(@PathVariable UUID organizationId,@PathVariable UUID id,@Valid @RequestBody ClinicalEncounterRequest r){return encounters.update(organizationId,id,r);}@PostMapping("/encounters/{id}/finalize") public ClinicalEncounterResponse finalizeRecord(@PathVariable UUID organizationId,@PathVariable UUID id,@RequestParam UUID clinicUnitId){return encounters.finalizeRecord(organizationId,clinicUnitId,id);}@PostMapping("/encounters/{id}/amendments") public ResponseEntity<ClinicalEncounterResponse> amend(@PathVariable UUID organizationId,@PathVariable UUID id,@Valid @RequestBody AmendEncounterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(encounters.amend(organizationId,id,r));}@GetMapping("/encounters/{id}/amendments") public List<ClinicalEncounterResponse> amendments(@PathVariable UUID organizationId,@PathVariable UUID id,@RequestParam UUID clinicUnitId){return encounters.amendments(organizationId,clinicUnitId,id);}
 @GetMapping("/odontogram/current") public List<OdontogramFindingResponse> current(@PathVariable UUID organizationId,@RequestParam UUID clinicUnitId,@RequestParam UUID patientId){return odontogram.current(organizationId,clinicUnitId,patientId);}@GetMapping("/odontogram/history") public PageResponse<OdontogramFindingResponse> history(@PathVariable UUID organizationId,@RequestParam UUID clinicUnitId,@RequestParam UUID patientId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return odontogram.history(organizationId,clinicUnitId,patientId,page,size);}@PostMapping("/odontogram/findings") public ResponseEntity<OdontogramFindingResponse> finding(@PathVariable UUID organizationId,@Valid @RequestBody OdontogramFindingCreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(odontogram.create(organizationId,r));}@PostMapping("/odontogram/findings/{id}/void") public OdontogramFindingResponse voidFinding(@PathVariable UUID organizationId,@PathVariable UUID id,@RequestParam UUID clinicUnitId,@Valid @RequestBody VoidOdontogramFindingRequest r){return odontogram.voidRecord(organizationId,clinicUnitId,id,r);}}
